def _hook_context(output: Path, freshness: dict[str, Any] | None = None) -> str:
    status = automation_status(output)
    fact_state = (freshness or status.get("fact_freshness") or {}).get("state", "unavailable")
    fact_action = (freshness or status.get("fact_freshness") or {}).get("next_action", {}).get("action", "retry-freshness-check")
    return (
        "当前会话已明确应用 code-knowledge-builder Skill，CKB 自动同步已激活：本轮事件会先进入脱敏、幂等的机器层队列。"
        f"源码事实新鲜度为 {fact_state}，下一入口为 {fact_action}。"
        f"当前待 Agent 审阅记录 {status['pending_reviews']} 条，失败事件 {status['failed_spool']} 条。"
        "分析和修改结论需使用简体中文核对来源后，再晋升到人类知识库。"
    )

def _hook_output(harness: str, event_name: str, context: str) -> dict[str, Any]:
    if event_name in {"SessionStart", "UserPromptSubmit"} and harness in {"codex", "claude", "dsh"}:
        return {
            "hookSpecificOutput": {
                "hookEventName": event_name,
                "additionalContext": context,
            }
        }
    if harness == "gemini" and event_name in {"SessionStart", "BeforeAgent"}:
        return {"hookSpecificOutput": {"additionalContext": context}}
    if harness == "cursor" and event_name == "sessionStart":
        return {"additional_context": context}
    return {}

def _heading_errors(text: str, changed: bool) -> list[str]:
    if not changed:
        return []
    headings = {
        re.sub(r"\s+", "", line.lstrip().lstrip("#").strip())
        for line in text.splitlines()
        if line.lstrip().startswith("#")
    }
    return [heading for heading in _CHANGE_HEADINGS if heading not in headings]

def search_automation(output: Path, question: str, limit: int = 8) -> list[dict[str, Any]]:
    path = output.resolve() / AUTOMATION_DATABASE
    if not path.is_file():
        return []
    terms = [value for value in re.findall(r"[\w\u3400-\u9fff.-]+", question.casefold()) if len(value) >= 2][:16]
    if not terms:
        return []
    query = " OR ".join('"' + value.replace('"', '""') + '"' for value in terms)
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        rows = [
            dict(row)
            for row in connection.execute(
                "SELECT p.review_id,p.title,p.kind,p.status,p.human_file,p.content,p.changed_paths_json,"
                "bm25(automation_fts,0.0,6.0,3.0,2.0) AS rank "
                "FROM automation_fts JOIN pending_reviews p USING(review_id) WHERE automation_fts MATCH ? ORDER BY rank, p.review_id LIMIT ?",
                (query, limit),
            )
        ]
    except sqlite3.OperationalError:
        rows = []
    finally:
        connection.close()
    for row in rows:
        row["changed_paths"] = json.loads(row.pop("changed_paths_json"))
    return rows

def harness_retrieval_contract(harness: str) -> dict[str, Any]:
    """Return the source-separated retrieval contract for one generated adapter."""

    if harness not in SUPPORTED_HARNESSES:
        raise CkbError(f"unsupported integration harness: {harness}")
    automatic, instruction_source = _PROJECT_INSTRUCTION_DISCOVERY[harness]
    discovery = ["explicit-task-binding"]
    if automatic:
        discovery.append(f"project-instruction:{instruction_source}")
    discovery.extend(("manager-context", "automation-registry"))
    return {
        "schema_version": 1,
        "harness": harness,
        "declaration_scope": "generated-contract-not-runtime-observation",
        "project_instruction": {
            "automatic_injection": automatic,
            "source": instruction_source,
            "runtime_observation": "not-observed-by-generator",
        },
        "manager_prompt": {
            "automatic_injection": False,
            "source": "manager context --format prompt",
            "runtime_observation": "not-observed-by-generator",
        },
        "skill": {
            "required": True,
            "exact_load": _EXACT_SKILL_LOADING[harness],
            "body_loaded_required": True,
            "runtime_observation": "requires-host-evidence",
        },
        "activation_registration": {
            "project": "automation register",
            "session": "canonical skill.applied event or automation activate",
            "required_for": ["event-sync", "resident-stdio"],
        },
        "output_discovery": {
            "ordered_sources": discovery,
            "directory_scan": False,
            "required_files": ["state.json", "machine/knowledge.sqlite"],
        },
        "execution": {
            "entry": "brief --profile fast",
            "pack_reopen_required": True,
            "record_reopen_required": True,
            "cli_fallback": True,
        },
        "non_blocking_for_retrieval": [
            "project-instruction-not-injected-when-skill-body-is-loaded",
            "manager-prompt-not-injected",
            "unrelated-harness-adapter-missing",
            "resident-stdio-unavailable",
        ],
    }

def _looks_windows(path: Path) -> bool:
    text = str(path)
    return (len(text) >= 3 and text[1:3] in {":\\", ":/"}) or text.startswith("\\\\")

def _wsl_launch_path(path: Path) -> str:
    """Return the WSL mount path for a drive-letter Windows executable."""
    if not _looks_windows(path):
        return str(path)
    windows = PureWindowsPath(str(path))
    drive = windows.drive
    if len(drive) == 2 and drive[1] == ":":
        return str(PurePosixPath("/mnt", drive[0].lower(), *windows.parts[1:]))
    return str(path)

